func newActivity() unsafe.Pointer { return unsafe.Pointer(new(collection.Activity)) }

func newNActivity(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]collection.Activity, n)))
}

func ptrActivity(p unsafe.Pointer, c int32) any {
	r := (*collection.Activity)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 5:
		return &r.Summary
	case 6:
		return &r.ContactName
	case 7:
		return (*string)(unsafe.Pointer(&r.InvoiceID))
	case 8:
		return &r.PromisedAmountMinor
	case 9:
		return &r.PromisedOn
	case 10:
		return &r.CurrencyCode
	case 11:
		return &r.FollowUpOn
	case 12:
		return (*string)(unsafe.Pointer(&r.CollectorID))
	case 13:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 14:
		return &r.CreatedAt
	}
	return nil
}

func valueActivity(p unsafe.Pointer, c int32) any {
	r := (*collection.Activity)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.CustomerID)
	case 4:
		return string(r.Kind)
	case 5:
		if r.Summary == "" {
			return nil
		}
		return r.Summary
	case 6:
		if r.ContactName == "" {
			return nil
		}
		return r.ContactName
	case 7:
		if r.InvoiceID == "" {
			return nil
		}
		return string(r.InvoiceID)
	case 8:
		if r.PromisedAmountMinor == nil {
			return nil
		}
		return *r.PromisedAmountMinor
	case 9:
		if r.PromisedOn == nil {
			return nil
		}
		return *r.PromisedOn
	case 10:
		return r.CurrencyCode
	case 11:
		if r.FollowUpOn == nil {
			return nil
		}
		return *r.FollowUpOn
	case 12:
		if r.CollectorID == "" {
			return nil
		}
		return string(r.CollectorID)
	case 13:
		return string(r.CreatedByID)
	case 14:
		return r.CreatedAt
	}
	return nil
}

func beforeCreateActivity(ctx context.Context, p unsafe.Pointer) error {
	return (*collection.Activity)(p).BeforeCreate(ctx)
}

